/* indusmova — the chat workspace.
 *
 * A conversation in the shape of the reference: a narrow icon rail, a
 * thread of bubbles, and a composer with voice and send. It is the same
 * engine the rest of the site uses — a message is resolved against
 * Wikipedia and Wikidata in the reader's language, and the reply carries
 * the source it came from. Nothing is generated by a model, so nothing is
 * invented.
 *
 * The embedded skill pack (../skills.js) only decides the shape of a
 * reply — a study question is answered in steps, a data question starts
 * with the definition. It is never shown as a list.
 */

import { el, esc, clamp, cleanUrl } from '../ui.js';
import { icon } from '../icons.js';
import { t } from '../i18n.js';
import { articleHref, searchHref } from '../router.js';
import { routeSkill, replyShape } from '../skills.js';

const KEY = 'indusmova:chat:v1';

/* ------------------------------------------------------------ storage */

function loadMessages() {
  try {
    const raw = localStorage.getItem(KEY);
    const list = raw ? JSON.parse(raw) : [];
    return Array.isArray(list) ? list.slice(-80) : [];
  } catch { return []; }
}

function saveMessages(list) {
  try { localStorage.setItem(KEY, JSON.stringify(list.slice(-80))); } catch { /* private mode */ }
}

/* --------------------------------------------------------------- brain */

/** Resolve a message to an encyclopedia page, or null. */
async function findPage(ctx, text) {
  const lang = ctx.state.contentLang;
  try {
    const direct = await ctx.api.resolveTitle(lang, text);
    if (direct) return direct;
  } catch { /* fall through to search */ }
  try {
    const hits = await ctx.api.search(lang, text, { limit: 3 });
    return hits?.[0]?.title || null;
  } catch { return null; }
}

/**
 * Compose a reply: the shape the skill pack chose, the encyclopedia's own
 * words, and the source attached. `support` never pretends to be an
 * encyclopedia answer.
 */
async function answer(ctx, text) {
  const skill = routeSkill(text);
  const shape = replyShape(skill?.mode || 'default');
  const lang = ctx.state.contentLang;

  if (skill?.mode === 'support') {
    return {
      text: `${shape.lead} I am here to help you think it through, and I will not guess at how you feel. If there is a fact behind it — a person, a place, a thing that happened — I can look that up properly and show you where it comes from.`,
      closing: shape.closing,
    };
  }

  const title = await findPage(ctx, text);
  if (title) {
    try {
      const page = await ctx.api.summary(lang, title);
      if (page?.extract) {
        return {
          text: page.extract,
          lead: shape.lead,
          closing: shape.closing,
          source: { title: page.title || title, href: articleHref(page.title || title, lang) },
        };
      }
    } catch { /* fall through */ }
  }

  return {
    text: `I could not find a published article for that in ${lang}.wikipedia.org, so I would rather say so than make something up.`,
    lead: shape.lead,
    closing: 'Try a name, a place, an event or a thing, and I will pull the article and keep its source attached.',
  };
}

/* ------------------------------------------------------------- pieces */

function avatar() {
  const span = el('span', { class: 'chat-avatar', 'aria-hidden': 'true' });
  span.innerHTML = `<svg viewBox="0 0 40 40"><defs><linearGradient id="cav" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#173b32"/><stop offset="1" stop-color="#b46a45"/></linearGradient></defs><rect width="40" height="40" rx="13" fill="url(#cav)"/><path d="M11.5 13.5h17a3.5 3.5 0 0 1 3.5 3.5v6.5a3.5 3.5 0 0 1-3.5 3.5h-7.2L16 30.6v-3.6h-4.5A3.5 3.5 0 0 1 8 23.5V17a3.5 3.5 0 0 1 3.5-3.5Z" fill="none" stroke="#f5f0e6" stroke-width="2" stroke-linejoin="round"/><path d="M15 18.4c1.7-2 3.3-2 5 0s3.3 2 5 0" fill="none" stroke="#f5f0e6" stroke-width="1.8" stroke-linecap="round"/></svg>`;
  return span;
}

function bubble(message) {
  const row = el('div', { class: `chat-row ${message.role}` });
  if (message.role === 'assistant') row.append(avatar());

  const body = el('div', { class: 'chat-bubble' });
  if (message.lead) body.append(el('p', { class: 'chat-lead', text: message.lead }));
  body.append(el('p', { text: clamp(message.text, 900) }));
  if (message.closing) body.append(el('p', { class: 'chat-closing', text: message.closing }));
  if (message.source) {
    const a = el('a', {
      class: 'chat-source', href: message.source.href,
      html: `${icon('sources')}<span>${esc(message.source.title)}</span>`,
    });
    body.append(a);
  }
  row.append(body);
  return row;
}

const SUGGESTIONS = [
  'What is the Unified Payments Interface?',
  'Who was Ashoka?',
  'How does photosynthesis work?',
  'When did Chandrayaan-3 land?',
];

function emptyState(onPick) {
  const box = el('div', { class: 'chat-empty' });
  box.append(avatar());
  box.append(el('h2', { text: 'Ask indusmova anything' }));
  box.append(el('p', { text: 'A question becomes a source-linked answer from Wikipedia and Wikidata. Every reply keeps the article it came from.' }));
  const chips = el('div', { class: 'chat-suggest' });
  for (const s of SUGGESTIONS) {
    const b = el('button', { type: 'button', class: 'chat-chip', text: s });
    b.addEventListener('click', () => onPick(s));
    chips.append(b);
  }
  box.append(chips);
  return box;
}

/* ----------------------------------------------------------- workspace */

/**
 * Build the chat. `docked` trims it for the side panel (no rail, tighter
 * header) and the route gets the full workspace.
 */
export function buildChat(ctx, { docked = false } = {}) {
  let messages = loadMessages();
  const shell = el('div', { class: `chat-shell${docked ? ' is-docked' : ''}` });
  const glow = el('div', { class: 'chat-glow', 'aria-hidden': 'true' });
  glow.innerHTML = '<i></i><i></i><i></i>';
  shell.append(glow);

  if (!docked) {
    const rail = el('nav', { class: 'chat-rail', 'aria-label': 'Chat' });
    const mk = (iconName, label, onClick) => {
      const b = el('button', { type: 'button', class: 'chat-rail-btn', 'aria-label': label, title: label });
      b.innerHTML = icon(iconName);
      b.addEventListener('click', onClick);
      return b;
    };
    rail.append(mk('plus', 'New chat', () => reset()));
    rail.append(mk('home', 'Back to the site', () => ctx.navigate('/')));
    rail.append(mk('history', 'Reading history', () => ctx.navigate('/history')));
    rail.append(mk('saved', 'Saved', () => ctx.navigate('/bookmarks')));
    shell.append(rail);
  }

  const main = el('section', { class: 'chat-main' });

  const head = el('header', { class: 'chat-head' });
  const titles = el('div', { class: 'chat-titles' });
  titles.append(el('h1', { text: docked ? 'Chat' : 'Chat with indusmova' }));
  titles.append(el('p', { text: 'Source-linked answers, in your language.' }));
  head.append(titles);
  const newBtn = el('button', { type: 'button', class: 'chat-new' });
  newBtn.innerHTML = `${icon('plus')}<span>New chat</span>`;
  newBtn.addEventListener('click', () => reset());
  head.append(newBtn);
  main.append(head);

  const thread = el('div', { class: 'chat-thread', id: 'chatThread', role: 'log', 'aria-live': 'polite' });
  main.append(thread);

  const form = el('form', { class: 'chat-composer' });
  const field = el('textarea', {
    rows: '1', placeholder: 'Ask anything…', 'aria-label': 'Message',
    autocomplete: 'off', id: 'chatInput',
  });
  const mic = el('button', { type: 'button', class: 'chat-icon', 'aria-label': t('voiceAria'), title: t('voiceAria') });
  mic.innerHTML = icon('mic');
  const send = el('button', { type: 'submit', class: 'chat-send', 'aria-label': 'Send' });
  send.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 12 20 4l-4.5 16-4-6.5L4 12Z"/></svg>';
  form.append(field, mic, send);
  main.append(form);
  shell.append(main);

  /* ---------------------------------------------------------- behaviour */

  function paint() {
    thread.innerHTML = '';
    if (!messages.length) { thread.append(emptyState(ask)); return; }
    for (const m of messages) thread.append(bubble(m));
    thread.scrollTop = thread.scrollHeight;
  }

  function reset() {
    messages = [];
    saveMessages(messages);
    paint();
    field.value = '';
    field.focus();
  }

  let busy = false;
  async function ask(text) {
    const value = String(text || '').trim();
    if (!value || busy) return;
    busy = true;
    messages.push({ role: 'user', text: value });
    saveMessages(messages);
    paint();

    const thinking = el('div', { class: 'chat-row assistant' });
    thinking.append(avatar());
    thinking.append(el('div', { class: 'chat-bubble chat-thinking', html: '<span></span><span></span><span></span>' }));
    thread.append(thinking);
    thread.scrollTop = thread.scrollHeight;

    let reply;
    try { reply = await answer(ctx, value); }
    catch { reply = { text: 'That lookup did not come back. Check the connection and ask me again.' }; }

    messages.push({ role: 'assistant', ...reply });
    saveMessages(messages);
    busy = false;
    paint();
  }

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const value = field.value;
    field.value = '';
    field.style.height = 'auto';
    ask(value);
  });
  field.addEventListener('input', () => {
    field.style.height = 'auto';
    field.style.height = `${Math.min(160, field.scrollHeight)}px`;
  });
  field.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault();
      form.requestSubmit();
    }
  });

  // Voice, where the browser offers it.
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (SR) {
    mic.addEventListener('click', () => {
      const rec = new SR();
      rec.lang = ctx.state.contentLang === 'hi' ? 'hi-IN' : 'en-IN';
      rec.interimResults = false;
      mic.classList.add('is-listening');
      rec.onresult = (e) => { field.value = e.results[0][0].transcript; field.focus(); };
      rec.onend = () => mic.classList.remove('is-listening');
      rec.onerror = () => mic.classList.remove('is-listening');
      try { rec.start(); } catch { mic.classList.remove('is-listening'); }
    });
  } else {
    mic.disabled = true;
    mic.title = t('voiceUnsupported');
  }

  paint();
  return shell;
}

/** The full-page chat. */
export async function renderChat(ctx) {
  const wrap = el('div', { class: 'chat-page' });
  wrap.append(buildChat(ctx));
  return wrap;
}

/* ------------------------------------------------------- the side dock */

let dockEl = null;

export function closeChatDock() {
  if (dockEl) { dockEl.remove(); dockEl = null; document.body.classList.remove('chat-dock-open'); }
}

export function toggleChatDock(ctx) {
  if (dockEl) { closeChatDock(); return; }
  dockEl = el('div', { class: 'chat-dock', role: 'dialog', 'aria-label': 'Chat' });
  const bar = el('div', { class: 'chat-dock-bar' });
  bar.append(el('span', { class: 'chat-dock-title', text: 'indusmova chat' }));
  const close = el('button', { type: 'button', class: 'chat-dock-close', 'aria-label': 'Close chat' });
  close.innerHTML = icon('close');
  close.addEventListener('click', closeChatDock);
  bar.append(close);
  dockEl.append(bar);
  dockEl.append(buildChat(ctx, { docked: true }));
  document.body.append(dockEl);
  document.body.classList.add('chat-dock-open');
  dockEl.querySelector('textarea')?.focus();
  document.addEventListener('keydown', function onKey(e) {
    if (e.key === 'Escape' && dockEl) { closeChatDock(); document.removeEventListener('keydown', onKey); }
  });
}
